Item.method_code:
string isAliasesIds = CCO.Permissions.AliasIdentitiesList.Trim('\'');

Item existingPreferenceItem = this.newItem("Preference", "get");
existingPreferenceItem.setProperty("identity_id", isAliasesIds);
existingPreferenceItem.setPropertyAttribute("identity_id", "condition", "in");
existingPreferenceItem = existingPreferenceItem.apply();

if (!existingPreferenceItem.isError())
{
	Item deleteExistingItem = this.newItem("Preference", "delete");
	deleteExistingItem.setID(existingPreferenceItem.getID());
	deleteExistingItem = deleteExistingItem.apply();

	if (deleteExistingItem.isError())
	{
		return deleteExistingItem;
	}
}

Item worldPreferenceItem = this.newItem();
worldPreferenceItem.loadAML(@"<Item type='Preference' action='get'>
	<identity_id>
		<Item type='Identity' action='get'>
			<name>World</name>
		</Item>
	</identity_id>
	<Relationships>
		<Item type='Core_GlobalLayout' action='get' />
		<Item type='SSVC_Preferences' action='get' />
	</Relationships>
</Item>");

worldPreferenceItem = worldPreferenceItem.apply();

Item preferenceItem = this.newItem("Preference", "add");
preferenceItem.setProperty("identity_id", isAliasesIds);

Item relationships = worldPreferenceItem.getRelationships();

for (int i = 0; i < relationships.getItemCount(); i++)
{
	Item relationship = relationships.getItemByIndex(i);

	Item newRelationship = relationship.clone(false);

	XmlNodeList nodesToRemove = newRelationship.node.SelectNodes("./*[local-name()='source_id' or local-name()='permission_id']");

	foreach (XmlNode nodeToRemove in nodesToRemove)
	{
		nodeToRemove.ParentNode.RemoveChild(nodeToRemove);
	}

	preferenceItem.addRelationship(newRelationship);
}

preferenceItem = preferenceItem.apply();

if (preferenceItem.isError())
{
	return preferenceItem;
}

Item resultItem = this.newItem("Preference", "get");
resultItem.setID(preferenceItem.getID());
resultItem.setAttribute("levels", "2");

return resultItem.apply();
